    // 循环查找，越过叶节点后跳出
    while (cur != null) {
      // 目标节点在 cur 的右子树中
      if (cur.val < _num)
        cur = cur.right;
      // 目标节点在 cur 的左子树中
      else if (cur.val > _num)
        cur = cur.left;
      // 找到目标节点，跳出循环
      else
        break;
    }
    // 返回目标节点
    return cur;
  }

  /* 插入节点 */
  void insert(int _num) {
    // 若树为空，则初始化根节点
    if (_root == null) {
      _root = TreeNode(_num);
      return;
    }
    TreeNode? cur = _root;
    TreeNode? pre = null;
