      // 找到重复节点，直接返回
      if (cur.val == _num) return;
      pre = cur;
      // 插入位置在 cur 的右子树中
      if (cur.val < _num)
        cur = cur.right;
      // 插入位置在 cur 的左子树中
      else
        cur = cur.left;
    }
    // 插入节点
    TreeNode? node = TreeNode(_num);
    if (pre!.val < _num)
      pre.right = node;
    else
      pre.left = node;
  }

  /* 删除节点 */
  void remove(int _num) {
    // 若树为空，直接提前返回
    if (_root == null) return;
    TreeNode? cur = _root;
    TreeNode? pre = null;
    // 循环查找，越过叶节点后跳出
    while (cur != null) {
      // 找到待删除节点，跳出循环
      if (cur.val == _num) break;
      pre = cur;
      // 待删除节点在 cur 的右子树中
      if (cur.val < _num)
        cur = cur.right;
      // 待删除节点在 cur 的左子树中
      else
        cur = cur.left;
    }
    // 若无待删除节点，直接返回
    if (cur == null) return;
    // 子节点数量 = 0 or 1
    if (cur.left == null || cur.right == null) {
      // 当子节点数量 = 0 / 1 时， child = null / 该子节点
      TreeNode? child = cur.left ?? cur.right;
      // 删除节点 cur
      if (cur != _root) {
        if (pre!.left == cur)
          pre.left = child;
        else
          pre.right = child;
      } else {
        // 若删除节点为根节点，则重新指定根节点
        _root = child;
      }
    } else {
      // 子节点数量 = 2
      // 获取中序遍历中 cur 的下一个节点
      TreeNode? tmp = cur.right;
      while (tmp!.left != null) {
